def score(self, x_test, y_test):
    """Evaluate model performance on a test set using mean squared error (MSE).

    @param x_test: a one-dimensional numpy array of features
    @param y_test: a one-dimensional numpy array of labels

    return value: float MSE over (x_test, y_test)

    Notes:
    - This method assumes the tree has already been trained.
    - Uses self.predict for each element in x_test.
    """
    if x_test.ndim != 1:
        raise ValueError("Input data set must be one-dimensional")
    if len(x_test) != len(y_test):
        raise ValueError("x and y have different lengths")
    if y_test.ndim != 1:
        raise ValueError("Data set labels must be one-dimensional")

    preds = np.array([self.predict(xi) for xi in x_test], dtype=float)
    return float(np.mean((y_test - preds) ** 2))

def mean_absolute_error(self, labels, prediction):
    """
    mean_absolute_error:
    @param labels: a one-dimensional numpy array
    @param prediction: a floating point value
    return value: mean_absolute_error calculates the error if prediction is used to
        estimate the labels
    """
    if labels.ndim != 1:
        print("Error: Input labels must be one dimensional")

    return np.mean(np.abs(labels - prediction))
